const DATA = {"years": [0.0, 0.0821, 0.1
"report": {"peak_cooling": 31.6, "yrs_freezing": 10.8, "yrs_dark": 9.4, "levels": [{"min": 0.01, "below10": 0.74, "recover": 17.5}, {"min": 0.0577, "below10": 5.56, "recover": 18.3}, {"min": 0.1911, "below10": null, "recover": 23.5}]}}, "soot": {"Ts": [288.0, 287.028, 286.072, 285.101, 284.177, 283.238, 282.344, 281.436, 280.573, 279.725, 278.864, 278.046, 277.217, 268.833, 263.592, 261.722, 262.4

function pad(s, w) { s = String(s); return ' '.repeat(Math.max(0, w - s.length)) + s; }
function report(key) {
  const r = DATA.scenarios[key].report, L = ['producers ', 'herbivores', 'predators '];
  let o = `<span class="h">${NAMES[key]}</span>\n`;
  o += `  peak cooling:          <span class="k">${pad(r.peak_cooling.toFixed(1), 5)} K</span>\n`;
  o += `  years below freezing:  <span class="k">${pad(r.yrs_freezing.toFixed(1), 5)}</span>\n`;
  o += `  years photosynth <10%: <span class="k">${pad(r.yrs_dark.toFixed(1), 5)}</span>\n\n`;
  r.levels.forEach((l, j) => {
    o += `  ${L[j]} min <span class="k">${(l.min * 100).toFixed(1)}%</span>\n`;
    o += l.below10 == null ? `    <span class="dim">never below 10%</span>\n` : `    below 10% at year <span class="k">${l.below10.toFixed(2)}</span>\n`;
    o += l.min >= 0.75 ? `    <span class="dim">never needed to recover</span>\n` : `    back to 75% at year <span class="k">${l.recover.toFixed(1)}</span>\n`;
  });
  if (key === 'neither') o += `\n<span class="dim">  No aerosols: temperature stays at\n  T0 = 288 K. Check passes.</span>`;
  document.getElementById('term').innerHTML = o;
}

